let tlTrial=null;function tlActive(){return tlTrial!=null}function tlIncoming(){return tlTrial?tlTrial.in:null}function tlOutgoingId(){return tlTrial?tlTrial.outId:null}function tlSquadWith(squad,incoming,outId){const base=squad||[];if(!incoming||outId==null)return base.slice();const out=base.find(p=>p.id===outId);return out?base.map(p=>p.id===outId?{...incoming,pickPosition:out.pickPosition,onBench:out.onBench,isCaptain:out.isCaptain,isViceCaptain:out.isViceCaptain,sellPrice:incoming.price,isTrialist:!0}:p):base.slice()}function tlEvaluate(squad,incoming,outId){if(typeof analyzePlayer!="function"||typeof computeSquadHealth!="function")return null;const before=squad||[];if(!incoming||!before.some(p=>p.id===outId))return null;const after=tlSquadWith(before,incoming,outId),xi=list=>list.filter(p=>p.pickPosition==null||p.pickPosition<=11),proj=p=>typeof predictedGWPoints=="function"?predictedGWPoints(p):0,total=list=>xi(list).reduce((s,p)=>s+proj(p)*(p.isCaptain?2:1),0),beforeHealth=computeSquadHealth(before.map(p=>analyzePlayer(p))),afterHealth=computeSquadHealth(after.map(p=>analyzePlayer(p))),out=before.find(p=>p.id===outId)||null,r1=v=>Math.round(v*10)/10;return{in:incoming,out,squad:after,xp:{before:r1(total(before)),after:r1(total(after)),delta:r1(total(after)-total(before))},health:{before:beforeHealth.health,after:afterHealth.health,delta:afterHealth.health-beforeHealth.health,breakdown:afterHealth.breakdown},money:(()=>{if(!out)return null;const bank=(typeof picksData<"u"&&picksData&&picksData.entry_history?picksData.entry_history.bank:0)/10,raised=(out.sellPrice!=null?out.sellPrice:out.price)+bank;return{raised:r1(raised),price:incoming.price,affordable:incoming.price<=raised+.001}})()}}function tlRenderBanner(result){if(!result)return"";const esc=typeof escHTML=="function"?escHTML:(s=>String(s??"")),sign=v=>(v>0?"+":"")+v,tone=v=>v>.05?"up":v<-.05?"down":"flat",money=result.money,moneyLine=money?money.affordable?`\xA3${money.price.toFixed(1)}m against the \xA3${money.raised.toFixed(1)}m selling ${esc(result.out.name)} would raise.`:`You could not afford him: \xA3${money.price.toFixed(1)}m against \xA3${money.raised.toFixed(1)}m.`:"";return`<div class="tl-banner">
                <div class="tl-head">
                    <span class="tl-tag">Trying</span>
                    <span class="tl-name">${esc(result.in.name)}</span>
                    ${result.out?`<span class="tl-swap">in place of ${esc(result.out.name)}</span>`:""}
                    <button type="button" class="tl-clear" onclick="tlClear()">Clear</button>
                </div>
                <div class="tl-deltas">
                    <div class="tl-delta" data-tooltip="Projected points for your starting eleven this gameweek, with the captain doubled \u2014 ${result.xp.before} now, ${result.xp.after} with him in.">
                        <span class="tl-delta-l">Starting XI</span>
                        <span class="tl-delta-v ${tone(result.xp.delta)}">${sign(result.xp.delta)} xP</span>
                    </div>
                    <div class="tl-delta" data-tooltip="The same squad health score as above, recalculated with him in the team \u2014 ${result.health.before} now, ${result.health.after} with him in.">
                        <span class="tl-delta-l">Squad health</span>
                        <span class="tl-delta-v ${tone(result.health.delta)}">${sign(result.health.delta)}</span>
                    </div>
                </div>
                ${moneyLine?`<p class="tl-money${money&&!money.affordable?" bad":""}">${esc(moneyLine)}</p>`:""}
                <p class="tl-note">He is not in your squad \u2014 this only changes the numbers on this page.
                   Make it real in the <a href="#transfers">Transfer Wizard</a>.</p>
            </div>`}function tlBadge(player){return player&&player.isTrialist?'<span class="tl-badge" data-tooltip="On trial \u2014 not in your squad. Nothing here has been transferred.">TRIAL</span>':""}function tlStart(playerId,outId){const incoming=(typeof allPlayers<"u"?allPlayers:[]).find(p=>p.id===Number(playerId));if(!incoming)return;if(selectedPlayers.some(p=>p.id===incoming.id)){typeof updateStatus=="function"&&updateStatus(`${incoming.name} is already in your squad`,"error");return}let out=outId!=null?selectedPlayers.find(p=>p.id===Number(outId)):null;if(!out){const proj=p=>typeof predictedGWPoints=="function"?predictedGWPoints(p):0,inPosition=selectedPlayers.filter(p=>p.position===incoming.position),starters=inPosition.filter(p=>!(p.pickPosition>11));out=(starters.length?starters:inPosition).sort((a,b)=>proj(a)-proj(b))[0]}out&&(tlTrial={in:incoming,outId:out.id},typeof renderTeamAnalysis=="function"&&renderTeamAnalysis())}function tlClear(){tlTrial&&(tlTrial=null,typeof renderTeamAnalysis=="function"&&renderTeamAnalysis())}function tlRenderInto(){if(!tlTrial||typeof selectedPlayers>"u")return"";const result=tlEvaluate(selectedPlayers,tlTrial.in,tlTrial.outId);return result?tlRenderBanner(result):""}function tlRenderPicker(){return typeof allPlayers>"u"||!allPlayers.length||tlTrial?"":`<div class="tl-picker">
                <input id="tlPick" class="tl-picker-in" list="tlPlayers" placeholder="Search a player you do not own\u2026"
                    aria-label="Try a player you do not own"
                    oninput="tlSuggest(this)" onchange="tlPickFromInput(this)" autocomplete="off">
                <datalist id="tlPlayers"></datalist>
            </div>`}function tlSuggest(el){const list=document.getElementById("tlPlayers");if(!list)return;const q=String(el&&el.value||"").trim().toLowerCase();if(q.length<2){list.innerHTML="";return}const esc=typeof escHTML=="function"?escHTML:(s=>String(s??"")),owned=new Set((selectedPlayers||[]).map(p=>p.id)),pool=typeof allPlayers<"u"?allPlayers:[];list.innerHTML=pool.filter(p=>!owned.has(p.id)&&p.status==="a"&&((p.name||"").toLowerCase().includes(q)||(p.team||"").toLowerCase().includes(q))).sort((a,b)=>(b.ownership||0)-(a.ownership||0)).slice(0,10).map(p=>`<option value="${esc(p.name)} \u2014 ${esc(p.team)} \xA3${p.price.toFixed(1)}m" data-id="${p.id}"></option>`).join("")}function tlPickFromInput(el){const raw=(el&&el.value||"").trim();if(!raw)return;const name=raw.split(" \u2014 ")[0].trim().toLowerCase(),owned=new Set((selectedPlayers||[]).map(p=>p.id)),match=(typeof allPlayers<"u"?allPlayers:[]).filter(p=>!owned.has(p.id)).find(p=>(p.name||"").toLowerCase()===name);if(!match){typeof updateStatus=="function"&&updateStatus(`No player called "${raw}" to try`,"error");return}tlStart(match.id)}function tlDisplayResults(){return!tlTrial||typeof analyzePlayer!="function"||typeof selectedPlayers>"u"?null:tlSquadWith(selectedPlayers,tlTrial.in,tlTrial.outId).map(p=>analyzePlayer(p))}
